use vstd::prelude::*;

verus! {

fn get_mini(a: &[i32]) -> (mini: usize)
    requires
        a.len() > 0,
    ensures
        mini < a.len(),
        // mini points to a minimal value
        forall|j: int| 0 <= j < a.len() ==> a[mini as int] <= a[j],
        // and is the leftmost occurrence of that minimal value
        forall|j: int| 0 <= j < mini as int ==> a[mini as int] < a[j],
{
    assert!(!a.is_empty(), "input array must be non-empty");

    let mut mini: usize = 0;
    let mut min_val: i32 = a[0];

    for (i, &v) in a.iter().enumerate().skip(1)
        invariant
            a.len() > 0,
            mini < a.len(),
            min_val == a[mini as int],
            // min_val is minimal among the prefix [0..i)
            forall|j: int| 0 <= j < i as int ==> min_val <= a[j],
            // mini is the leftmost index achieving min_val within [0..i)
            forall|j: int| 0 <= j < mini as int ==> min_val < a[j],
        decreases a.len() - i,
    {
        if v < min_val {
            min_val = v;
            mini = i;
        }
        // If v == min_val, we do nothing to keep the first (leftmost) occurrence.
    }

    mini
}

} // verus!
